            new Quote { Id = "https://tr.wikiquote.org/wiki/Sait_Faik_Abasıyanık", Text = "Ben bir acayip oldum. Gözüm kimseyi görmüyor, kimsenin kapımı çalmasını istemiyorum.", Author = "Sait Faik Abasıyanık" },
